catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    var paymentRequired = (newValue == 'yes'); // Change 'yes' if your value is different

    // Payment fields
    // g_form.setDisplay('u_currency', paymentRequired);
    g_form.setMandatory('u_currency', false);

    // g_form.setDisplay('u_course_fee', paymentRequired);
    g_form.setMandatory('u_course_fee', paymentRequired);

    // g_form.setDisplay('u_other_expenses', paymentRequired);
    g_form.setMandatory('u_other_expenses', false);

    // g_form.setDisplay('u_specify_other_expenses', paymentRequired);
    g_form.setMandatory('u_specify_other_expenses', false);

    // g_form.setDisplay('u_total_cost', paymentRequired);

    // g_form.setDisplay('is_l2_approval_required', paymentRequired);
    g_form.setDisplay('l2_manager', paymentRequired);

    // Make read-only when hidden
    g_form.setReadOnly('u_currency', !paymentRequired);
    g_form.setReadOnly('u_course_fee', !paymentRequired);
    g_form.setReadOnly('u_other_expenses', !paymentRequired);
    g_form.setReadOnly('u_specify_other_expenses', !paymentRequired);
    g_form.setReadOnly('u_total_cost', !paymentRequired);
    g_form.setReadOnly('u_l2_required', !paymentRequired);
    g_form.setReadOnly('u_management_l2', !paymentRequired);

    // Optional: Clear values when Payment Required = No
    if (!paymentRequired) {
        // g_form.clearValue('u_currency');
        g_form.clearValue('u_course_fee');
        g_form.clearValue('u_other_expenses');
        g_form.clearValue('u_specify_other_expenses');
        g_form.clearValue('u_total_cost');
        g_form.clearValue('u_l2_required');
        g_form.clearValue('u_management_l2');
    }
}
